import assert from 'node:assert/strict';
import fs from 'node:fs';
import vm from 'node:vm';
const read=p=>fs.readFileSync(new URL(p,import.meta.url),'utf8');
const context=vm.createContext({});
vm.runInContext(read('./dist/renal-math.js'),context);
const calc=vm.runInContext('RenalMath',context);
const input={age:60,sex:'male',creatinine:1,unit:'mgdl',equation:'ckdepi2021',context:'stable',deindex:false};
const result=overrides=>calc.compute({...input,...overrides});
// Published NKF Table S1 verification values, not outputs generated by this app.
// https://www.kidney.org/recommendations-implementing-ckd-epi-2021-race-free-egfr-calculation-guidelines-clinical
const published=[[18,'male',0.90,127],[18,'male',0.91,125],[18,'female',0.70,128],[18,'female',0.71,126],[90,'male',0.50,97],[90,'male',1.50,44],[90,'female',0.50,89],[90,'female',1.50,33]];
for(const [age,sex,creatinine,expected] of published){
  const mg=result({age,sex,creatinine});assert.equal(mg.ok,true);assert.equal(Math.round(mg.indexed),expected);
  const si=result({age,sex,creatinine:creatinine*88.4,unit:'umol'});assert.equal(si.ok,true);assert.ok(Math.abs(si.indexed-mg.indexed)<1e-10);
}
// Independent scalar evaluation of the published IDMS MDRD equation (no race multiplier).
for(const [age,sex,creatinine,expected] of [[60,'male',1,76.22077229137905],[60,'female',1,56.555813040203255],[40,'male',2,37.190434769827505],[40,'female',2,27.59530259921201],[90,'male',1.5,43.96605575559401],[90,'female',1.5,32.62281337065076]]){
  const a=result({age,sex,creatinine,equation:'mdrd'});assert.ok(Math.abs(a.indexed-expected)<1e-10);assert.match(a.warnings.join(' '),/Legacy MDRD.*race multiplier.*omitted/);
  assert.ok(Math.abs(result({age,sex,creatinine:creatinine*88.4,unit:'umol',equation:'mdrd'}).indexed-expected)<1e-10);
}
for(const [sex,knot] of [['male',0.9],['female',0.7]]){
  const left=result({sex,creatinine:knot-1e-10}).indexed,right=result({sex,creatinine:knot+1e-10}).indexed;
  assert.ok(Math.abs(left-right)<1e-6,'Equation must be continuous across the creatinine splice');
}
const bsa=result({deindex:true,height:180,weight:80});assert.equal(bsa.bsa,2);assert.ok(Math.abs(bsa.absolute-bsa.indexed*2/1.73)<1e-12);
assert.equal(result({deindex:false,height:0,weight:0}).absolute,null);
for(const overrides of [{age:''},{age:0},{age:17},{age:121},{age:Infinity},{sex:''},{sex:'x'},{creatinine:''},{creatinine:0},{creatinine:-1},{creatinine:NaN},{creatinine:Infinity},{creatinine:'<0.1'},{unit:'mg/L'},{context:''},{context:'aki'},{context:'dialysis'},{context:'pregnancy'},{equation:'2009'},{deindex:true,height:'',weight:70},{deindex:true,height:170,weight:''},{deindex:true,height:49,weight:70},{deindex:true,height:170,weight:501}]){
  const x=result(overrides);assert.equal(x.ok,false,JSON.stringify(overrides));assert.equal('indexed' in x,false,'No number may survive validation failure');assert.ok(x.message);
}
assert.equal(result({age:18}).ok,true);assert.equal(result({age:120}).ok,true);
assert.equal(result({creatinine:0.15}).warnings.length,1);
const data=JSON.parse(read('./dist/database.json')),old=JSON.parse(read('./baseline_v07.json'));
assert.equal(data.version,'0.8.0');assert.equal(data.clinicalDataVersion,'0.7.0');
assert.deepEqual(data.drugs,old.drugs);assert.deepEqual(data.sources,old.sources);assert.deepEqual(data.sharedGuidance,old.sharedGuidance);assert.deepEqual(data.sourceConflicts,old.sourceConflicts);
assert.equal(data.calculatorSources.length,6);
const html=read('./dist/index.html');assert.ok(html.includes(read('./dist/renal-math.js')));assert.ok(html.includes(read('./dist/calculator.js')));assert.match(html,/id="calculator"/);
assert.ok(!/localStorage|sessionStorage|fetch\s*\(|downloadText|setHash|location\./.test(read('./dist/calculator.js')),'Calculator values must not be persisted, exported or sent');
assert.match(read('./dist/app.js'),/!\$\('#calculator'\)\.open/,'Drug-search shortcut must not run over the calculator');
console.log('PASS: NKF Table S1 reference cases in both units; independent MDRD examples; splice, BSA and validation cases; unchanged v0.7 clinical records; embedded calculator and no persistence/export/network path.');
